package com.prestige.notification.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="notification", uniqueConstraints=@UniqueConstraint(name="uq_notification_event_customer_role", columnNames={"event_id","customer_id","role"}))
public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="notification_id") private Long id; @Column(name="event_id",nullable=false) private String eventId; @Column(name="customer_id",nullable=false) private Long customerId; @Column(nullable=false) private String role; @Column(nullable=false) private String type; @Column(nullable=false) private String title; @Column(nullable=false) private String body; @Column(nullable=false) private BigDecimal amount; @Column(name="transfer_reference",nullable=false) private String transferReference; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @Column(name="read_at") private LocalDateTime readAt;
 protected Notification() { }
 public Notification(String eventId,Long customerId,String role,String title,String body,BigDecimal amount,String ref,LocalDateTime created) {this.eventId=eventId;this.customerId=customerId;this.role=role;this.type="TRANSFER_COMPLETED";this.title=title;this.body=body;this.amount=amount;this.transferReference=ref;this.createdAt=created;} public void markRead(){if(readAt==null) readAt=LocalDateTime.now();}
 public Long getId(){return id;} public Long getCustomerId(){return customerId;} public String getRole(){return role;} public String getType(){return type;} public String getTitle(){return title;} public String getBody(){return body;} public BigDecimal getAmount(){return amount;} public String getTransferReference(){return transferReference;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getReadAt(){return readAt;}
}
